<script setup lang="ts">
import {ref,computed} from 'vue'
const radius=ref(15),noise=ref(0),hard=ref(true)
const data=[{name:'A',x:7,y:2,d:.3},{name:'B',x:13,y:-5,d:1.4},{name:'C',x:33,y:8,d:.25},{name:'D',x:-37,y:-11,d:2.7},{name:'E',x:5,y:24,d:.6},{name:'F',x:-10,y:5,d:1.1}]
const candidates=computed(()=>data.map(p=>({...p,distance:Math.hypot(p.x+noise.value,p.y)})))
const negative=computed(()=>candidates.value.filter(p=>p.distance>radius.value+10).sort((a,b)=>hard.value?a.d-b.d:b.d-a.d)[0])
</script>
<template><div class="lab-grid"><svg class="lab-svg" viewBox="0 0 530 270" role="img" aria-label="Sélection géographique des paires"><path d="M25 145H500M255 15V250" stroke="#d0d9df" stroke-width="25"/><circle cx="255" cy="140" :r="(radius+10)*2.5" fill="#fff0dc" style="opacity:.7"/><circle cx="255" cy="140" :r="radius*2.5" fill="#d3eddb" style="opacity:.8"/><g v-for="p in candidates" :key="p.name"><circle :cx="255+(p.x+noise)*2.5" :cy="140-p.y*2.5" :r="negative?.name===p.name?10:7" :fill="p.distance<=radius?'#218638':p.distance<=radius+10?'#F15A22':'#CF1C24'"/><text :x="267+(p.x+noise)*2.5" :y="135-p.y*2.5">{{p.name}}</text></g><circle cx="255" cy="140" r="8" fill="#087fa1"/><text x="269" y="158">Requête</text><text x="15" y="263">Vert : positif possible · orange : zone ignorée</text></svg><div class="lab-readout" data-testid="mining"><p>Positifs possibles : <b>{{candidates.filter(p=>p.distance<=radius).map(p=>p.name).join(', ')||'aucun'}}</b></p><p>Négatif {{hard?'difficile':'facile'}} : <strong>{{negative?.name||'aucun'}}</strong></p><p v-if="negative">Distance GNSS : {{negative.distance.toFixed(1)}} m<br/>Distance descripteurs : {{negative.d.toFixed(2)}}</p><p>Proximité géographique et ressemblance visuelle répondent à deux critères distincts.</p></div></div><div class="lab-controls"><label>Rayon positif<input aria-label="Rayon positif" v-model.number="radius" type="range" min="5" max="22"/>{{radius}} m</label><label>Biais GNSS<input aria-label="Biais GNSS" v-model.number="noise" type="range" min="-12" max="12"/>{{noise}} m</label><label><input aria-label="Négatif difficile" v-model="hard" type="checkbox"/>Négatif difficile</label></div></template>
